def positive_prefix(values):
    count = 0
    for value in values:
        if value <= 0:
            break
        count += 1
    return count

def replace_negatives(values):
    result = []
    for value in values:
        if value < 0:
            result.append(0)
        else:
            result.append(value)
    return result

def adjacent_increases(values):
    count = 0
    for i in range(1, len(values)):
        if values[i] > values[i - 1]:
            count += 1
    return count

def frequent_first(values):
    if not values:
        return None
    counts = {}
    for value in values:
        counts[value] = counts.get(value, 0) + 1
    best = values[0]
    for value in values:
        if counts[value] > counts[best]:
            best = value
    return best

def balance_cut(values):
    total = sum(values)
    left = 0
    for k in range(len(values) + 1):
        if left == total - left:
            return k
        if k < len(values):
            left += values[k]
    return -1

def running_maxima(values):
    result = []
    for value in values:
        if not result or value > result[-1]:
            result.append(value)
        else:
            result.append(result[-1])
    return result

def sum_distinct(values):
    seen = []
    total = 0
    for value in values:
        if value not in seen:
            seen.append(value)
            total += value
    return total

